import{_ as a,c as n,o as e,af as l}from"./chunks/framework.BivmJ8bT.js";const u=JSON.parse('{"title":"AI概率汇总","description":"","frontmatter":{},"headers":[],"relativePath":"docs/AIGC/01-名词说明.md","filePath":"docs/AIGC/01-名词说明.md","lastUpdated":1774860900000}'),i={name:"docs/AIGC/01-名词说明.md"};function o(s,t,p,r,g,h){return e(),n("div",null,t[0]||(t[0]=[l(`<h1 id="ai概率汇总" tabindex="-1">AI概率汇总 <a class="header-anchor" href="#ai概率汇总" aria-label="Permalink to &quot;AI概率汇总&quot;">​</a></h1><ul><li>LLM</li><li>Agent</li><li>Token</li><li>Context</li><li>Prompt</li><li>MCP</li></ul><p><code>LLM</code> 是服务员的大脑，代表其核心的理解与思考能力；</p><p><code>Token</code> 是你和服务员沟通的字数单位；</p><p><code>Context/Context Window</code> 是服务员的记忆容量，决定它能够记住多少你的需求；</p><p><code>Prompt</code> 是你向服务员下达的指令，包含规则与具体需求；</p><p><code>Tool/MCP</code> 是服务员可以调用的各类工具，例如计算器、后厨、外卖系统等；</p><p><code>Agent/Agent Skill</code> 则对应服务员的角色定位与专业技能，比如专业点餐员搭配智能推荐菜品的能力。</p><h2 id="llm" tabindex="-1">LLM <a class="header-anchor" href="#llm" aria-label="Permalink to &quot;LLM&quot;">​</a></h2><h3 id="什么是-llm" tabindex="-1">什么是 LLM <a class="header-anchor" href="#什么是-llm" aria-label="Permalink to &quot;什么是 LLM&quot;">​</a></h3><p><code>LLM</code>，全称 <strong>Large Language Model</strong>，翻译过来就是 <strong>大语言模型</strong></p><p>LLM 的工作原理基本上就是依据极其庞大的数据量的学习来进行「预测下一个字」。</p><p>LLM 其实有点像一个<code>&quot;有嘴没手&quot;</code> 的顾问。</p><h3 id="llm-有什么缺点" tabindex="-1">LLM 有什么缺点 <a class="header-anchor" href="#llm-有什么缺点" aria-label="Permalink to &quot;LLM 有什么缺点&quot;">​</a></h3><ul><li><p>只会「说」不会「做」。</p><p>LLM 的能力被困在对话框里，它没法跟外部世界互动，没法操作任何系统。让他修改代码BUG，它没办法去操作编辑器去改文件、跑测试。</p></li><li><p>没有「记忆」</p><p>LLM 的记忆只限于当前这轮对话的上下文窗口，对话一结束，一切归零。</p></li><li><p>不会用「工具」</p><p>LLM 本身不能上网搜索、不能查数据库、不能调 API，所有回答都来自它「脑子里」已有的知识，这些知识不仅有截止日期，还可能是错的，也就是常说的「幻觉」问题。</p></li><li><p>不会「规划」。</p><p>LLM 是「被动响应型」的，你问一句它答一句，没法自主拆解任务、制定计划、分步执行。</p></li></ul><blockquote><p>那么有没有一种方式，能让 LLM 不仅会「说」，还能「做」呢？这就是 <code>Agent</code> 要解决的问题。</p></blockquote><h2 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h2><h3 id="什么是agent" tabindex="-1">什么是Agent <a class="header-anchor" href="#什么是agent" aria-label="Permalink to &quot;什么是Agent&quot;">​</a></h3><p>Agent，翻译过来叫<strong>智能体</strong>。</p><p><strong>Agent 就是 LLM 在循环中自主使用工具的系统。</strong></p><p>「LLM」说明 Agent 的核心大脑还是大模型，「工具」说明它能调用外部能力，「循环」说明它不是一问一答就结束，而是会不断地思考、行动、观察结果、再思考，直到任务完成。</p><h3 id="agent-怎么解决-llm-的弊端" tabindex="-1">Agent 怎么解决 LLM 的弊端？ <a class="header-anchor" href="#agent-怎么解决-llm-的弊端" aria-label="Permalink to &quot;Agent 怎么解决 LLM 的弊端？&quot;">​</a></h3><ul><li><p>针对&quot;只会说不会做&quot;，Agent 引入了<strong>工具调用</strong>能力，可以调用搜索引擎、数据库、API、代码执行器等各种外部工具来真正执行操作。</p></li><li><p>针对&quot;没有记忆&quot;，Agent 配备了<strong>记忆系统</strong>，包括记住当前任务上下文的短期记忆，和存储在外部数据库中、可以跨对话保留的长期记忆。</p></li><li><p>针对&quot;不会用工具&quot;，业界推出了 MCP 等<strong>标准化协议</strong>来统一工具接入方式。</p></li><li><p>针对&quot;不会规划&quot;，Agent 具备了<strong>任务拆解和规划</strong>能力，能把一个大目标分解成多个小步骤，然后逐步执行。</p></li></ul><h3 id="agent-的核心组成" tabindex="-1">Agent 的核心组成 <a class="header-anchor" href="#agent-的核心组成" aria-label="Permalink to &quot;Agent 的核心组成&quot;">​</a></h3><p>一个完整的 Agent 应该是以下四个模块的组合</p><p>第一个是<strong>大脑</strong>，也就是 LLM，负责理解意图、推理判断、决定下一步行动。</p><p>第二个是<strong>规划模块</strong>，负责把复杂任务拆解成可执行的步骤。</p><p>第三个是<strong>记忆模块</strong>，负责存储和检索信息，让 Agent 能在长时间任务中保持连贯。</p><p>第四个是<strong>工具模块</strong>，是 Agent 的「手和脚」，让它能跟外部世界互动。</p><p>![image-20260330135022006](/img/ai agent-diagram.png)</p><h3 id="agent-和-workflow-有什么区别" tabindex="-1">Agent 和 Workflow 有什么区别？ <a class="header-anchor" href="#agent-和-workflow-有什么区别" aria-label="Permalink to &quot;Agent 和 Workflow 有什么区别？&quot;">​</a></h3><h4 id="两者的定义" tabindex="-1"><strong>两者的定义</strong> <a class="header-anchor" href="#两者的定义" aria-label="Permalink to &quot;**两者的定义**&quot;">​</a></h4><p><strong>Workflow 是指 LLM 和工具通过预定义的代码路径进行编排的系统</strong>，而 <strong>Agent 是指 LLM 动态主导自身流程与工具调用的系统，由 LLM 自主决定如何完成任务</strong>。</p><p>![image-20260330135022000](/img/ai compare-workflow&amp;agent.png)</p><p>Workflow 是「我（开发者）告诉你每一步该做什么」，Agent 是「我告诉你目标，你自己决定怎么做」。</p><p>Workflow 就像一条工厂流水线，每个工位做什么、零件从哪来到哪去，全都是提前设计好的。工人（LLM）只需要在自己的工位上完成指定动作。</p><p>而 Agent 更像一个自主工作的项目经理，老板只告诉他&quot;把这件事搞定&quot;，然后他自己去调研、制定计划、协调资源、推进执行。</p><h4 id="核心区别" tabindex="-1">核心区别 <a class="header-anchor" href="#核心区别" aria-label="Permalink to &quot;核心区别&quot;">​</a></h4><p>两者最核心的区别在于**「谁在控制流程」**</p><p>Workflow 的控制权在代码手里，流程是确定的、可预测的、可复现的，但灵活性比较差。</p><p>Agent 的控制权在 LLM 手里，行为是动态的、灵活的、能适应变化的，但相应地也带来了不确定性。</p><p>在实际生产环境中，最常见的其实是<strong>混合架构</strong>，Workflow 和 Agent 的结合。正如 LangChain 说的：&quot;大多数生产中的 Agent 系统其实是 Workflow 和 Agent 的组合。&quot;</p><h3 id="agent有什么工作模式" tabindex="-1">Agent有什么工作模式 <a class="header-anchor" href="#agent有什么工作模式" aria-label="Permalink to &quot;Agent有什么工作模式&quot;">​</a></h3><h4 id="模式一-react-边想边做" tabindex="-1"><strong>模式一：ReAct（边想边做）</strong> <a class="header-anchor" href="#模式一-react-边想边做" aria-label="Permalink to &quot;**模式一：ReAct（边想边做）**&quot;">​</a></h4><p>ReAct 是目前最经典、最基础的 Agent 工作模式，名字来源于 Reasoning + Acting 的缩写，也就是「推理 + 行动」。几乎所有主流的 Agent 框架底层都在用它。</p><p>![image-20260330141403165](/img/ai agent-reAct.png)</p><p>核心思想非常简单：Agent 在思考和行动之间不断交替。具体来说就是一个三步循环，先是<strong>思考（Thought）</strong>，分析当前情况决定下一步做什么；然后是<strong>行动（Action）</strong>，调用一个工具来执行；接着是<strong>观察（Observation）</strong>，查看工具返回的结果。然后回到思考，如此循环，直到任务完成。</p><h4 id="模式二-plan-and-execute-先想好再做" tabindex="-1">模式二：Plan-and-Execute（先想好再做） <a class="header-anchor" href="#模式二-plan-and-execute-先想好再做" aria-label="Permalink to &quot;模式二：Plan-and-Execute（先想好再做）&quot;">​</a></h4><p>它把 Agent 的工作分成两个阶段：第一阶段是规划，Agent 先把完整的执行计划想清楚；第二阶段是执行，按计划逐步完成，不用每步都重新思考全局。</p><p>![image-20260330143845413](/img/ai plan&amp;exextue.png.png)</p><p>这种模式最大的优势是规划只做一次，执行阶段不用反复推理。</p><p>但缺点是不够灵活，如果执行到第 3 步发现情况变了，原来的计划可能就不适用了。所以也有这么个做法是在执行过程中加入「重新规划检查点」，每隔几步检查一下计划是否还靠谱。</p><h4 id="模式三-reflection-做完再检查" tabindex="-1">模式三：Reflection（做完再检查） <a class="header-anchor" href="#模式三-reflection-做完再检查" aria-label="Permalink to &quot;模式三：Reflection（做完再检查）&quot;">​</a></h4><p>反思模式的核心思想是 Agent 完成任务后不急着交付，而是先自我检查一遍，就像你写完文章不会直接发出去，而是再通读一遍、改一改、润色一下。</p><p>![image-20260330144105863](/img/ai reflection.png)</p><p>实现方法有两种</p><ul><li><strong>自我反思</strong>，同一个 Agent 完成任务后切换到「审查者」角色来审视自己的输出，发现问题就修改，然后再审查，直到满意</li><li><strong>双 Agent 对话</strong>，一个 Agent 负责生成，另一个负责评审，两者来回迭代直到评审方满意，就像代码的 Code Review 过程。这种模式特别适合对质量要求高的场景，比如代码生成、法律文书、学术论文等</li></ul><h4 id="模式四-multi-agent-团队协作" tabindex="-1">模式四：Multi-Agent（团队协作） <a class="header-anchor" href="#模式四-multi-agent-团队协作" aria-label="Permalink to &quot;模式四：Multi-Agent（团队协作）&quot;">​</a></h4><p>Multi-Agent 模式让多个专业化的 Agent 各司其职，比如一个负责规划、一个负责搜集信息、一个负责写代码、一个负责测试，通过协作来完成复杂任务</p><p>![image-20260330144241995](/img/ai agent-multi.png)</p><p>Anthropic 提醒过：<strong>不要过早引入多 Agent 架构</strong>。很多时候，一个强大的单 Agent 就够用了。只有任务确实需要拆分成多个并行子任务时，多 Agent 才值得引入。</p><p>这几种模式不是互斥的，实际中往往是组合使用的。一个多 Agent 系统中，每个 Agent 内部可能用的是 ReAct 模式，整体协作用的是 Multi-Agent 模式，最后还有一个 Reflection 环节来检查质量。</p><h3 id="function-call-函数调用" tabindex="-1">Function Call（函数调用） <a class="header-anchor" href="#function-call-函数调用" aria-label="Permalink to &quot;Function Call（函数调用）&quot;">​</a></h3><p>「工具调用」，Agent 能查天气、能搜索信息、能操作数据库，这些能力是怎么实现的？</p><p>—— <strong>Function Call（函数调用）</strong></p><p>从「只会说话」到「能做事情」</p><h4 id="function-call-的工作原理" tabindex="-1">Function Call 的工作原理 <a class="header-anchor" href="#function-call-的工作原理" aria-label="Permalink to &quot;Function Call 的工作原理&quot;">​</a></h4><p>![image-20260330144946799](/img/ai function-call.png)</p><ul><li><p>第一步，<strong>定义函数</strong></p></li><li><p>第二步，<strong>模型判断</strong></p></li><li><p>第三步，<strong>执行函数</strong></p><p><strong>LLM 自己并不执行函数</strong>。它只是输出了「我想调用这个函数，参数是这些」的结构化指令。真正执行函数的是你的应用程序。</p></li><li><p>第四步，<strong>生成回答</strong></p></li></ul><p>Function Call 解决了两个核心问题</p><ul><li><p>第一个是**&quot;什么时候调用&quot;的判断问题**，LLM 能根据用户的自然语言意图，自动判断需不需要调用工具、调用哪个工具。你不需要写复杂的条件判断逻辑，LLM 自己会推理。</p></li><li><p>第二个是**&quot;传什么参数&quot;的提取问题**，LLM 能从用户的自然语言中提取出结构化的参数。用户说&quot;帮我查一下北京后天的天气&quot;，LLM 能自动提取出 <code>city=北京</code> 和 <code>date=后天</code>。</p></li></ul><blockquote><p>Function Call 就是 Agent 能力的最底层技术基础</p></blockquote><h4 id="function-call-和-agent-的关系" tabindex="-1">Function Call 和 Agent 的关系 <a class="header-anchor" href="#function-call-和-agent-的关系" aria-label="Permalink to &quot;Function Call 和 Agent 的关系&quot;">​</a></h4><p>Function Call 是一次性的「单步调用」，LLM 判断需要调用一个函数，调用完就结束了。</p><p>Agent 是「循环调用」，Agent 在一个循环中反复使用 Function Call，每次调用后观察结果，再决定下一步要不要继续调用其他函数。</p><p>![image-20260330145426398](/img/ai function call &amp; agent.png)</p><p>Function Call 是 Agent 的「原子操作」，Agent 是 Function Call 的「高级编排」。一个 Agent 完成一个复杂任务，可能需要连续进行十几次 Function Call。</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>Function Call 让 LLM 能调用工具。但随着 Agent 越来越强大，需要连接的工具和服务越来越多，一个新问题浮出水面了，<strong>集成太麻烦了</strong>。</p><p>Function Call 的集成困境</p><p>![image-20260330145805042](/img/ai function call dilemma.png)</p><p>用 Function Call 的方式，你需要为每一个服务单独写适配代码，为 Slack 写一套函数定义和调用逻辑、为 Google Drive 写一套、为 GitHub 写一套、为数据库又写一套。</p><p>如果你有 N 个 AI 应用，要对接 M 个外部服务，就需要写 N × M 个定制集成。</p><h3 id="mcp-的诞生" tabindex="-1">MCP 的诞生 <a class="header-anchor" href="#mcp-的诞生" aria-label="Permalink to &quot;MCP 的诞生&quot;">​</a></h3><p>Anthropic 在 2024 年 11 月开源了 <strong>MCP（Model Context Protocol，模型上下文协议）</strong>。可以把 MCP 理解为**「AI 界的 USB-C 接口」**</p><p>![image-20260330150134623](/img/ai MCP.png)</p><p>它提供了一个<strong>统一的标准</strong>，让任何 AI 应用都能用同一种方式连接任何外部工具和数据源。</p><h3 id="mcp-是怎么工作的" tabindex="-1">MCP 是怎么工作的？ <a class="header-anchor" href="#mcp-是怎么工作的" aria-label="Permalink to &quot;MCP 是怎么工作的？&quot;">​</a></h3><p>![image-20260330150659636](/img/ai mcp brief.png)</p><p>MCP 的架构主要有三个角色。</p><ul><li><strong>MCP Host（宿主）</strong>，就是你使用的 AI 应用，比如 Claude Desktop、Cursor 编辑器、你自己开发的 Agent 应用。它是整个交互的发起方。</li><li><strong>MCP Client（客户端）</strong>，它住在 Host 里面，负责跟 MCP Server 通信。你可以把它理解为&quot;翻译官&quot;，Host 想要什么能力，Client 就去跟对应的 Server 沟通。</li><li><strong>MCP Server（服务端）</strong>，它负责对外暴露具体的工具能力和数据资源。比如有一个 GitHub MCP Server，它能提供&quot;搜索代码&quot;&quot;创建 Issue&quot;&quot;查看 PR&quot;等工具。一个 Slack MCP Server 能提供&quot;发送消息&quot;&quot;搜索频道&quot;等工具。</li></ul><p>用户在 AI 应用中提问 → AI 应用（Host）通过 MCP Client 发现有哪些可用工具 → AI 决定调用某个工具 → MCP Client 向对应的 MCP Server 发送请求 → Server 执行操作返回结果 → AI 基于结果生成回答。</p><p>![image-20260330151104223](/img/ai mcp workflow.png)</p><h3 id="mcp-解决了什么问题" tabindex="-1">MCP 解决了什么问题？ <a class="header-anchor" href="#mcp-解决了什么问题" aria-label="Permalink to &quot;MCP 解决了什么问题？&quot;">​</a></h3><p>最核心的就是把 N × M 的集成问题变成了 N + M 的问题。</p><p>以前每个 AI 应用要跟每个服务单独对接，现在每个 AI 应用只要支持 MCP 协议（实现一次 Client），每个服务只要提供一个 MCP Server（实现一次 Server），双方就能自动对接。</p><p>新增一个服务不需要改任何 AI 应用的代码，新增一个 AI 应用也不需要改任何服务的代码。</p><p>而且 MCP Server 暴露的工具是<strong>可发现的</strong>，AI 应用启动时能自动查询有哪些 MCP Server 可用、每个 Server 提供哪些工具、每个工具的参数是什么。</p><p>这意味着 Agent 可以在运行时动态发现新的能力，而不是只能用开发者写死的那些函数</p><h2 id="skills-技能" tabindex="-1">Skills（技能） <a class="header-anchor" href="#skills-技能" aria-label="Permalink to &quot;Skills（技能）&quot;">​</a></h2><p>Function Call 让 Agent 能调用函数，MCP 让 Agent 用统一标准连接工具</p><p>Agent 知道怎么调用工具了，但它知道在什么场景下该用什么方法来解决问题吗？</p><h3 id="skills-是什么" tabindex="-1">Skills 是什么 <a class="header-anchor" href="#skills-是什么" aria-label="Permalink to &quot;Skills 是什么&quot;">​</a></h3><p>Skills 是一种<strong>自然语言指令文件</strong>，通常是 Markdown 格式，用来教 Agent&quot;在什么场景下、按照什么方法、遵循什么规范来完成特定任务&quot;。</p><p>在 Claude Code、Cursor 等 AI 工具中，Skills 通常以 <code>SKILL.md</code> 文件的形式存在。</p><p>![image-20260330151824623](/img/ai skills what.png)</p><p>Skills 的结构很简单：顶部有一段 YAML 格式的元数据，声明这个 Skill 什么时候应该被激活（比如&quot;当用户要求代码审查时&quot;）；下面是具体的行为指令，用自然语言写成。</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: Code_Review_Expert</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 当用户要求进行代码审查时，自动触发此技能。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">triggers:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - &quot;帮我 review 一下这段代码&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - &quot;代码审查&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 身份设定</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一个拥有 10 年开发经验的资深后端架构师，你极其看重代码的可读性、性能和安全性。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 审查工作流</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">当你进行代码审查时，你必须严格按照以下步骤进行排查：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1. 看结构：检查代码是否符合单一职责原则，有没有超过 100 行的超长方法。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2. 查漏洞：重点检查是否存在 SQL 注入风险、越权访问风险或空指针异常风险。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3. 审性能：是否有在 for 循环里查数据库的愚蠢操作？是否有流对象没有及时 close 释放？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4. 给方案：你绝对不能只挑毛病，必须针对每个问题给出具体的修改建议，并且附带优化后的代码片段。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 输出规范</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">语气要专业、极其直接，不要说废话。直接输出一份 Markdown 格式的审查报告，分点列出问题和修改方案。</span></span></code></pre></div><p>MCP 解决的是&quot;能做什么&quot;的问题，Skills 解决的是&quot;该怎么做&quot;的问题</p><h3 id="skills-的工作方式" tabindex="-1">Skills 的工作方式 <a class="header-anchor" href="#skills-的工作方式" aria-label="Permalink to &quot;Skills 的工作方式&quot;">​</a></h3><p>Skills 的工作方式跟 Function Call 和 MCP 有本质不同。</p><p>Function Call 和 MCP 都是让 Agent &quot;执行外部操作&quot;，调用 API、查询数据库、发送消息，这些操作发生在 Agent 外部。</p><p>而 Skills <strong>完全在 Agent 内部运行</strong>，它不调用任何外部服务，而是被加载到 Agent 的上下文窗口中，改变 Agent 的思考和行为方式。</p><p>具体来说，当 Agent 启动时，它会扫描可用的 Skills 列表。当用户提出请求时，Agent 判断有没有匹配的 Skill。如果有，Agent 就把这个 Skill 的内容加载到上下文中，然后按照 Skill 中的指令来思考和行动。</p><p>这就像给 Agent 「临时注入了一段专业经验」。没加载 Skill 之前，Agent 只有通用能力；加载了特定 Skill 之后，Agent 在这个领域就变成了专家。</p><h3 id="skills-有什么价值" tabindex="-1">Skills 有什么价值？ <a class="header-anchor" href="#skills-有什么价值" aria-label="Permalink to &quot;Skills 有什么价值？&quot;">​</a></h3><p>Skills 的核心价值在于<strong>将专业知识和最佳实践编码成可复用的模块</strong>。</p><p>![image-20260330152144809](/img/ai skills charge.png)</p><h2 id="function-call、mcp、skills-有什么区别" tabindex="-1">Function Call、MCP、Skills 有什么区别？ <a class="header-anchor" href="#function-call、mcp、skills-有什么区别" aria-label="Permalink to &quot;Function Call、MCP、Skills 有什么区别？&quot;">​</a></h2><p>Agent 是一个新入职的员工。</p><p><strong>Function Call 就是&quot;打电话的能力&quot;</strong>，<strong>MCP 就是&quot;公司的通讯录和电话系统&quot;</strong>，<strong>Skills 就是&quot;岗位培训手册&quot;</strong></p><p>![image-20260330152817661](/img/ai agent three.png)</p><p>三者的区别体现在几个维度上</p><p>![image-20260330152924464](/img/ai agent skills mcp.png)</p><p>从<strong>解决的问题</strong>来看</p><ul><li><p>Function Call 解决的是&quot;LLM 怎么跟外部函数交互&quot;这个最基础的问题。</p><ul><li>MCP 解决的是&quot;怎么用统一标准管理大量工具&quot;的集成问题。</li><li>Skills 解决的是&quot;Agent 怎么获得领域专业知识&quot;的知识问题。</li></ul></li></ul><p>从<strong>运行位置</strong>来看</p><ul><li>Function Call 的函数在你的应用程序中执行。</li><li>MCP 的工具在外部的 MCP Server 中执行。</li><li>Skills 完全在 Agent 的上下文窗口内生效，不涉及任何外部调用。</li></ul><p>从<strong>技术本质</strong>来看</p><ul><li>Function Call 是一种 API 协议，LLM 输出结构化的调用请求，应用程序执行后返回结果。</li><li>MCP 是一种通信标准，定义了 Client 和 Server 之间如何发现和调用工具。</li><li>Skills 是一种提示词扩展，用自然语言编写的行为指令，加载到 Agent 的上下文中。</li></ul><p>从<strong>标准化程度</strong>来看</p><ul><li>Function Call 在各 LLM 厂商之间格式不统一（OpenAI 和 Anthropic 的格式就不一样）。</li><li>MCP 是统一的开放标准，跨厂商通用。</li><li>Skills 目前还没有统一标准，各个 Agent 平台有自己的 Skill 格式。</li></ul><h3 id="三者是什么关系" tabindex="-1">三者是什么关系？ <a class="header-anchor" href="#三者是什么关系" aria-label="Permalink to &quot;三者是什么关系？&quot;">​</a></h3><p>![image-20260330153155233](/img/ai summary.png)</p><p>Function Call 是<strong>底层基础</strong>。MCP 建立在 Function Call 之上，提供了标准化的包装。当你的 Agent 通过 MCP 调用一个工具时，底层其实还是在做 Function Call，只不过格式和通信方式被 MCP 统一了。</p><h2 id="a2a" tabindex="-1">A2A <a class="header-anchor" href="#a2a" aria-label="Permalink to &quot;A2A&quot;">​</a></h2><p>如果有多个 Agent 需要互相协作，它们之间怎么通信？</p><h3 id="为什么需要-a2a" tabindex="-1">为什么需要 A2A？ <a class="header-anchor" href="#为什么需要-a2a" aria-label="Permalink to &quot;为什么需要 A2A？&quot;">​</a></h3><p>当一个新员工入职时，需要 HR Agent 处理入职手续、IT Agent 配置工作电脑和账号、财务 Agent 设置薪资账户。这三个 Agent 需要协作，但它们互相不认识，也不知道对方会什么、怎么沟通。</p><p>MCP 解决不了这个问题，因为 MCP 是给 Agent 连接&quot;工具&quot;用的，它处理的是&quot;Agent 调用数据库&quot;&quot;Agent 发送邮件&quot;这类 Agent 与工具之间的交互。</p><p>但 Agent 与 Agent 之间的协作，需要一个全新的协议。</p><p>![image-20260330153600541](/img/ai why-a2a.png)</p><h3 id="什么是-a2a-协议" tabindex="-1">什么是 <strong>A2A</strong> 协议？ <a class="header-anchor" href="#什么是-a2a-协议" aria-label="Permalink to &quot;什么是 **A2A** 协议？&quot;">​</a></h3><p>A2A 是 Google 在 2025 年 4 月的 Google Cloud Next 大会上发布的一个<strong>开放协议</strong>，全称 Agent-to-Agent Protocol，顾名思义就是&quot;Agent 对 Agent&quot;的通信协议。它联合了超过 50 家合作伙伴共同推出，包括 Atlassian、Salesforce、SAP、MongoDB、LangChain 等业界大玩家。</p><p>A2A 定义了一套标准，让不同的 AI Agent 能够<strong>互相发现、互相通信、互相委派任务</strong>，不管这些 Agent 是用什么框架开发的、运行在什么平台上。</p><h3 id="a2a-的核心概念" tabindex="-1">A2A 的核心概念 <a class="header-anchor" href="#a2a-的核心概念" aria-label="Permalink to &quot;A2A 的核心概念&quot;">​</a></h3><p>![image-20260330153800069](/img/ai a2a-concept.png)</p><ul><li><p><strong>Agent Card（智能体名片）</strong></p><p>每个支持 A2A 的 Agent 都会发布一个 JSON 格式的&quot;名片&quot;，描述自己的身份、能力、擅长的领域、支持的交互方式、认证要求等信息。其他 Agent 通过读取这个名片来了解&quot;这个 Agent 会什么，我能请它帮什么忙&quot;。这就像你在 LinkedIn 上看到一个人的简历，知道他的技能和经验后，才决定要不要跟他合作。</p></li><li><p><strong>任务（Task）</strong></p><p>A2A 中的所有协作都围绕&quot;任务&quot;展开。一个 Client Agent（发起方）创建一个任务，发送给一个 Remote Agent（执行方）。任务有完整的生命周期，从创建、处理中、到完成或失败，每个状态变化都有明确的定义。这让双方能清楚地跟踪任务进展。</p></li><li><p><strong>消息和制品（Message &amp; Artifact）</strong></p><p>Agent 之间通过消息来沟通过程中的信息，通过制品来传递最终结果。比如一个研究 Agent 完成分析后，会把分析报告作为制品返回给请求方。</p></li></ul><h3 id="a2a-和-mcp-是什么关系" tabindex="-1">**A2A 和 MCP 是什么关系？ <a class="header-anchor" href="#a2a-和-mcp-是什么关系" aria-label="Permalink to &quot;**A2A 和 MCP 是什么关系？&quot;">​</a></h3><p><strong>MCP 是「竖向」的，处理 Agent 到工具的连接；A2A 是「横向」的，处理 Agent 到 Agent 的协作。</strong></p><p>Google 的官方设计中，两者是互补的关系，被明确设计为可以共同使用。在一个典型的多 Agent 系统中，一个编排 Agent 通过 A2A 协议把任务委派给不同的专业 Agent，而每个专业 Agent 内部通过 MCP 来连接它自己需要的工具。</p><p>协议的边界很清晰：Agent 之间的通信走 A2A，Agent 调用工具走 MCP。</p><p>![image-20260330154055073](/img/ai a2a&amp;mcp.png)</p><p>目前整个 Agent 协议生态正在形成一个清晰的分层格局：<strong>Function Call 提供底层调用能力，MCP 标准化 Agent 与工具的连接，A2A 标准化 Agent 与 Agent 的协作</strong></p><hr><p><a href="https://mp.weixin.qq.com/s/82Aj1X1SX1-megVaQ1TcCQ" target="_blank" rel="noreferrer">Agent 相关的核心概念-万字长文图解</a></p>`,156)]))}const d=a(i,[["render",o]]);export{u as __pageData,d as default};
